// Definicion estricta de los 4 modelos de la interfaz Gemini:
// Respeta SIEMPRE el modelo exacto elegido (Pro nunca baja a Flash) y el Nivel de pensamiento exacto (Alto, Medio, Bajo).
class OpcionModeloGemini {
  final String id;
  final String titulo;
  final String subtitulo;
  final List<String> endpointsEstrictos;
  final int budgetAlto;
  final int budgetMedio;
  final int budgetBajo;
  final double temperature;
  final String instruccionExtra;

  const OpcionModeloGemini({
    required this.id,
    required this.titulo,
    required this.subtitulo,
    required this.endpointsEstrictos,
    required this.budgetAlto,
    required this.budgetMedio,
    required this.budgetBajo,
    required this.temperature,
    required this.instruccionExtra,
  });

  int obtenerThinkingBudget(String nivelPensamiento) {
    if (nivelPensamiento == 'Bajo') return budgetBajo;
    if (nivelPensamiento == 'Medio') return budgetMedio;
    return budgetAlto; // 'Alto' por defecto
  }
}

