// Extrae cuantos segundos pide esperar Google cuando devuelve 429 (ej. "retryDelay": "5s")
int extraerSegundosEspera429(String errorBody, int intentoActual) {
  try {
    final m = RegExp(r'retryDelay"\s*:\s*"(\d+)').firstMatch(errorBody) ??
        RegExp(r'retry in (\d+)').firstMatch(errorBody.toLowerCase());
    if (m != null) {
      final seg = int.tryParse(m.group(1) ?? '');
      if (seg != null && seg > 0) {
        return seg.clamp(2, 8);
      }
    }
  } catch (_) {}
  return (3 + (intentoActual * 2)).clamp(3, 7);
}

// Detecta UNICAMENTE si se agoto la cuota DIARIA real (PerDay), sin confundirla con limites por minuto (free_tier_requests)
bool esCuotaDiariaAgotada429(String errorBody) {
  final lower = errorBody.toLowerCase();
  if (RegExp(r'retrydelay"\s*:\s*"(\d+)').hasMatch(lower)) {
    final m = RegExp(r'retrydelay"\s*:\s*"(\d+)').firstMatch(lower);
    final seg = int.tryParse(m?.group(1) ?? '') ?? 0;
    if (seg > 0 && seg <= 45) {
      return false;
    }
  }
  return lower.contains('per_day') ||
      lower.contains('perday') ||
      lower.contains('requestsperday');
}

String normalizarAModeloDeLosCuatro(String? raw) {
  final s = (raw ?? '').trim();
  for (final m in kCuatroModelosGemini) {
    if (m.id == s || m.subtitulo == s || m.titulo == s) {
      return m.id;
    }
  }
  final lower = s.toLowerCase();
  if (lower.contains('lite') || lower.contains('3.5')) {
    return '3.5 Flash-Lite';
  }
  if (lower.contains('hydrogen') || lower.contains('flash')) {
    return '4 Hydrogen';
  }
  if (lower.contains('3.1') || lower.contains('pro')) {
    return '3.1 Pro';
  }
  return '4 Argon';
}

OpcionModeloGemini obtenerConfigGlobalModelo(String idBuscado) {
  final norm = normalizarAModeloDeLosCuatro(idBuscado);
  for (final m in kCuatroModelosGemini) {
    if (m.id == norm) return m;
  }
  return kCuatroModelosGemini[2];
}

String formatearNumeroConComas(int valor) {
  final s = valor.toString();
  final reg = RegExp(r'(\d{1,3})(?=(\d{3})+(?!\d))');
  return s.replaceAllMapped(reg, (Match m) => '${m[1]},');
}

String construirEtiquetaVerificada({
  required String modelo,
  required String nivelPensamiento,
  required int tokensRazonados,
}) {
  if (tokensRazonados > 0) {
    return '$modelo • Pensamiento $nivelPensamiento (${formatearNumeroConComas(tokensRazonados)} tokens razonados)';
  }
  return '$modelo • Pensamiento $nivelPensamiento';
}

// Respaldo en Isolate por si se descarga un PPTX desde un link de Google Drive en bytes
String extraerTextoPptxOptimizadoEnIsolate(List<int> bytes) {
  final archive = ZipDecoder().decodeBytes(bytes);
  final slidesBuffer = StringBuffer();

  final slideFiles = archive.files
      .where((f) =>
          f.name.startsWith('ppt/slides/slide') && f.name.endsWith('.xml'))
      .toList();

  slideFiles.sort((a, b) {
    final numA = int.tryParse(
            RegExp(r'slide(\d+)\.xml').firstMatch(a.name)?.group(1) ?? '0') ??
        0;
    final numB = int.tryParse(
            RegExp(r'slide(\d+)\.xml').firstMatch(b.name)?.group(1) ?? '0') ??
        0;
    return numA.compareTo(numB);
  });

  final regExpParrafo = RegExp(r'<a:p\b[^>]*>(.*?)</a:p>', dotAll: true);
  final regExpTexto = RegExp(r'<a:t[^>]*>(.*?)</a:t>', dotAll: true);
  final frasesGlobalesVistas = <String>{};

  for (int i = 0; i < slideFiles.length; i++) {
    final file = slideFiles[i];
    final content =
        utf8.decode(file.content as List<int>, allowMalformed: true);
    final parrafos = regExpParrafo.allMatches(content);
    final lineasSlide = <String>[];
    final vistasEnSlide = <String>{};

    for (final p in parrafos) {
      final pContent = p.group(1) ?? '';
      final textos = regExpTexto
          .allMatches(pContent)
          .map((m) => m.group(1) ?? '')
          .join('')
          .replaceAll('&amp;', '&')
          .replaceAll('&lt;', '<')
          .replaceAll('&gt;', '>')
          .replaceAll('&quot;', '"')
          .replaceAll('&apos;', "'")
          .replaceAll(RegExp(r'\s+'), ' ')
          .trim();

      if (textos.isEmpty) continue;
      lineasSlide.add(textos);
    }

    if (lineasSlide.isNotEmpty) {
      slidesBuffer.writeln('[Diapositiva ${i + 1}] ${lineasSlide.join(" • ")}');
    }
  }
  return slidesBuffer.toString().trim();
}

