class EjercicioResuelto {
  final String id;
  final String? rutaImagen;
  final DateTime fecha;
  String autor;
  String modeloUsado;
  String nivelPensamientoUsado;
  int tokensRazonados;
  String? nombrePptUsado;
  String? instruccionAdicional;
  String? solucion;
  bool procesando;
  String estadoCola;
  int progreso;
  List<Map<String, dynamic>> mensajesChat;

  EjercicioResuelto({
    required this.id,
    this.rutaImagen,
    required this.fecha,
    this.autor = 'Local',
    required this.modeloUsado,
    this.nivelPensamientoUsado = 'Alto',
    this.tokensRazonados = 0,
    this.nombrePptUsado,
    this.instruccionAdicional,
    this.solucion,
    this.procesando = true,
    this.estadoCola = 'En cola',
    this.progreso = 0,
    List<Map<String, dynamic>>? mensajesChat,
  }) : mensajesChat = mensajesChat ?? [];

  String get etiquetaModeloCompleta => construirEtiquetaVerificada(
        modelo: modeloUsado,
        nivelPensamiento: nivelPensamientoUsado,
        tokensRazonados: tokensRazonados,
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'rutaImagen': rutaImagen,
        'imagenBase64': _obtenerBase64SyncDeRuta(rutaImagen),
        'fecha': fecha.toIso8601String(),
        'autor': autor,
        'modeloUsado': modeloUsado,
        'nivelPensamientoUsado': nivelPensamientoUsado,
        'tokensRazonados': tokensRazonados,
        'nombrePptUsado': nombrePptUsado,
        'instruccionAdicional': instruccionAdicional,
        'solucion': solucion,
        'procesando': procesando,
        'estadoCola': estadoCola,
        'progreso': progreso,
        'mensajesChat': mensajesChat,
      };

  static String? _obtenerBase64SyncDeRuta(String? path) {
    if (path == null) return null;
    try {
      final f = File(path);
      if (f.existsSync() && f.lengthSync() < 2 * 1024 * 1024) {
        return base64Encode(f.readAsBytesSync());
      }
    } catch (_) {}
    return null;
  }

  factory EjercicioResuelto.fromJson(Map<String, dynamic> json) {
    final rawChat = json['mensajesChat'] as List?;
    final parsedChat = <Map<String, dynamic>>[];
    if (rawChat != null) {
      for (final item in rawChat) {
        if (item is Map) {
          parsedChat.add(Map<String, dynamic>.from(item));
        }
      }
    }
    String? rutaFinal = json['rutaImagen'];
    final b64Remota = json['imagenBase64']?.toString();
    final idStr = json['id'] ?? DateTime.now().millisecondsSinceEpoch.toString();

    if (b64Remota != null && b64Remota.isNotEmpty) {
      try {
        final bytes = base64Decode(b64Remota);
        if (bytes.isNotEmpty) {
          final tempDir = Directory.systemTemp;
          final cacheFile = File('${tempDir.path}/saycheese_remota_$idStr.jpg');
          if (!cacheFile.existsSync() || cacheFile.lengthSync() != bytes.length) {
            cacheFile.writeAsBytesSync(bytes, flush: true);
          }
          if (cacheFile.existsSync()) {
            rutaFinal = cacheFile.path;
          }
        }
      } catch (_) {}
    }

    return EjercicioResuelto(
      id: idStr,
      rutaImagen: rutaFinal,
      fecha: DateTime.tryParse(json['fecha'] ?? '') ?? DateTime.now(),
      autor: json['autor'] ?? 'Compañero',
      modeloUsado: normalizarAModeloDeLosCuatro(json['modeloUsado']?.toString()),
      nivelPensamientoUsado: json['nivelPensamientoUsado']?.toString() ?? 'Alto',
      tokensRazonados: (json['tokensRazonados'] as num?)?.toInt() ?? 0,
      nombrePptUsado: json['nombrePptUsado'],
      instruccionAdicional: json['instruccionAdicional'],
      solucion: json['solucion'],
      procesando: json['procesando'] ?? false,
      estadoCola: json['estadoCola'] ?? 'Listo',
      progreso: (json['progreso'] as int?) ?? 100,
      mensajesChat: parsedChat,
    );
  }
}

class PptCompartido {
  final String id;
  final String nombre;
  final String autor;
  final String textoExtraido;
  final String? rutaLocalPdf;
  final DateTime fecha;

  PptCompartido({
    required this.id,
    required this.nombre,
    required this.autor,
    required this.textoExtraido,
    this.rutaLocalPdf,
    required this.fecha,
  });

  int get numeroDiapositivas {
    final matches = RegExp(r'\[(Diapositiva\s+|S)\d+\]').allMatches(textoExtraido).length;
    return matches > 0 ? matches : 1;
  }

  Map<String, dynamic> toJson() => {
        'id': id,
        'nombre': nombre,
        'autor': autor,
        'textoExtraido': textoExtraido,
        'rutaLocalPdf': rutaLocalPdf,
        'fecha': fecha.toIso8601String(),
      };

  factory PptCompartido.fromJson(Map<String, dynamic> json) => PptCompartido(
        id: json['id'] ?? DateTime.now().millisecondsSinceEpoch.toString(),
        nombre: json['nombre'] ?? 'Presentacion PPT',
        autor: json['autor'] ?? 'Compañero',
        textoExtraido: json['textoExtraido'] ?? '',
        rutaLocalPdf: json['rutaLocalPdf'],
        fecha: DateTime.tryParse(json['fecha'] ?? '') ?? DateTime.now(),
      );
}

