  Future<void> _actualizarNotificacionProgreso({
    required int porcentaje,
    required String titulo,
    required String detalle,
    bool forzarNotificacionNativa = false,
  }) async {
    final pct = porcentaje.clamp(0, 100);
    if (mounted) {
      setState(() {
        _progresoActualPorcentaje = pct;
        _textoEstadoNotificacion = '$titulo ($pct%) — $detalle';
      });
    }
    final ahora = DateTime.now();
    final cambioSuficiente = (pct - _ultimoPorcentajeNotif).abs() >= 2;
    final tiempoSuficiente =
        ahora.difference(_ultimoPushNotif).inMilliseconds >= 350;
    if (forzarNotificacionNativa ||
        pct == 100 ||
        _ultimoPorcentajeNotif < 0 ||
        (cambioSuficiente && tiempoSuficiente)) {
      _ultimoPorcentajeNotif = pct;
      _ultimoPushNotif = ahora;
      try {
        await _notifChannel.invokeMethod('showProgress', {
          'title': '$titulo ($pct%)',
          'body': detalle,
          'progress': pct,
          'maxProgress': 100,
          'indeterminate': false,
        });
      } catch (_) {}
    }
  }

  Future<void> _reportarProgresoReal({
    required EjercicioResuelto ejercicio,
    required int porcentaje,
    required String fase,
    int totalEnCola = 1,
    bool forzarNotificacion = false,
  }) async {
    final pct = porcentaje.clamp(0, 100);
    final sufijoCola =
        totalEnCola > 1 ? ' • Cola: ${totalEnCola - 1} pendiente(s)' : '';
    if (mounted) {
      setState(() {
        ejercicio.progreso = pct;
        ejercicio.estadoCola = fase;
      });
    } else {
      ejercicio.progreso = pct;
      ejercicio.estadoCola = fase;
    }
    await _actualizarNotificacionProgreso(
      porcentaje: pct,
      titulo: 'Resolviendo con ${ejercicio.modeloUsado}',
      detalle: '$fase$sufijoCola',
      forzarNotificacionNativa: forzarNotificacion,
    );
  }

