  // Selector nativo ultrarrapido: Kotlin ya extrae el texto de los .pptx en <0.1s sin congelar nada
  Future<void> _abrirSelectorNativoPpt({StateSetter? setModalState}) async {
    try {
      if (mounted) setState(() => _cargandoPpts = true);
      setModalState?.call(() {});
      final List<dynamic>? archivos =
          await _notifChannel.invokeMethod<List<dynamic>>('pickPptFiles');
      if (archivos == null || archivos.isEmpty) return;

      int slot = 0;
      for (final item in archivos.take(2)) {
        if (item is Map) {
          final nombre =
              (item['name']?.toString() ?? 'Presentacion.pptx').trim();
          final textoDirecto = item['text']?.toString() ?? '';
          final b64 = item['base64']?.toString() ?? '';

          if (textoDirecto.isNotEmpty) {
            await _agregarOActivarPpt(
              nombre: nombre,
              textoExtraido: textoDirecto,
              autor: _aliasUsuario,
              slotForzado: archivos.length == 2 ? slot : null,
            );
          } else if (b64.isNotEmpty) {
            final bytes = base64Decode(b64);
            await _procesarBytesDeArchivoSubido(
              nombre,
              bytes,
              slotForzado: archivos.length == 2 ? slot : null,
            );
          }
          slot++;
        }
      }
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content: Text(
                  '⚡ ${_pptsActivos.length}/2 PPT(s) listos en modo ultrarrápido.')),
        );
      }
    } catch (_) {
      if (mounted) {
        _mostrarExploradorInternoDeArchivos(paraFoto: false);
      }
    } finally {
      if (mounted) setState(() => _cargandoPpts = false);
      setModalState?.call(() {});
    }
  }

  // Extrae el texto completo de todas las diapositivas/paginas de un archivo PDF para que las reglas y ejemplos esten 100% disponibles tanto localmente como en la Sala en Vivo
  Future<String> _extraerTextoCompletoDePdf(
      List<int> bytes, String nombre) async {
    final keyLimpia = _apiKey.trim();
    if (keyLimpia.isEmpty || bytes.isEmpty || bytes.length > 15 * 1024 * 1024) {
      return '';
    }
    try {
      final redOk = await _esperarRedDisponible(maxIntentos: 6);
      if (!redOk) return '';
      final b64Pdf = base64Encode(bytes);
      final payload = {
        "contents": [
          {
            "parts": [
              {
                "text":
                    "Transcribe íntegramente TODO el texto, reglas, definiciones, fórmulas, cuadros y ejemplos de todas las páginas/diapositivas de este documento PDF ($nombre). "
                    "Numera cada página o diapositiva con el formato '[Diapositiva 1] ...', '[Diapositiva 2] ...'. "
                    "No omitas ninguna regla, nota ni ejemplo porque se usará como fuente estricta de verdad para resolver ejercicios."
              },
              {
                "inline_data": {
                  "mime_type": "application/pdf",
                  "data": b64Pdf,
                }
              }
            ]
          }
        ],
        "generationConfig": {
          "maxOutputTokens": 8192,
          "temperature": 0.0,
        }
      };

      for (final mod in ['gemini-3-flash-preview', 'gemini-3.1-pro-preview']) {
        try {
          final url = Uri.parse(
              'https://generativelanguage.googleapis.com/v1beta/models/$mod:generateContent?key=$keyLimpia');
          final res = await _httpClient
              .post(
                url,
                headers: {'Content-Type': 'application/json'},
                body: jsonEncode(payload),
              )
              .timeout(const Duration(seconds: 16));
          if (res.statusCode == 200) {
            final data = jsonDecode(res.body) as Map<String, dynamic>;
            final cands = data['candidates'] as List? ?? [];
            if (cands.isNotEmpty) {
              final content = cands[0]['content'] as Map<String, dynamic>?;
              final parts = content?['parts'] as List? ?? [];
              final sb = StringBuffer();
              for (final p in parts) {
                if (p is Map && p['thought'] != true && p['text'] != null) {
                  sb.write(p['text'].toString());
                }
              }
              final txt = sb.toString().trim();
              if (txt.length > 40) {
                return txt;
              }
            }
          }
        } catch (_) {}
      }
    } catch (_) {}
    return '';
  }

  Future<void> _procesarBytesDeArchivoSubido(
    String nombre,
    List<int> bytes, {
    String? rutaArchivoOriginal,
    int? slotForzado,
  }) async {
    final ext = nombre.toLowerCase();
    if (ext.endsWith('.pptx')) {
      String textoFinal = '';
      if (rutaArchivoOriginal != null && rutaArchivoOriginal.isNotEmpty) {
        try {
          textoFinal = await _notifChannel.invokeMethod<String>(
                'extractPptxFromPath',
                {'path': rutaArchivoOriginal},
              ) ??
              '';
        } catch (_) {}
      }
      if (textoFinal.isEmpty) {
        textoFinal =
            await compute(extraerTextoPptxOptimizadoEnIsolate, bytes);
      }
      if (textoFinal.isEmpty) {
        throw Exception('No se encontro texto legible dentro del PPTX.');
      }
      await _agregarOActivarPpt(
        nombre: nombre,
        textoExtraido: textoFinal,
        autor: _aliasUsuario,
        slotForzado: slotForzado,
      );
    } else if (ext.endsWith('.pdf')) {
      String rutaPdfFinal = rutaArchivoOriginal ?? '';
      if (rutaPdfFinal.isEmpty || !File(rutaPdfFinal).existsSync()) {
        final tempDir = Directory.systemTemp;
        final safeName = nombre.replaceAll(RegExp(r'[^a-zA-Z0-9._-]'), '_');
        rutaPdfFinal =
            '${tempDir.path}/saycheese_pdf_${DateTime.now().millisecondsSinceEpoch}_$safeName';
        await File(rutaPdfFinal).writeAsBytes(bytes, flush: true);
      }
      String textoExtraidoPdf = await _extraerTextoCompletoDePdf(bytes, nombre);
      await _agregarOActivarPpt(
        nombre: nombre,
        textoExtraido: textoExtraidoPdf.isNotEmpty
            ? textoExtraidoPdf
            : '[PDF Activo: $nombre]',
        autor: _aliasUsuario,
        rutaLocalPdf: rutaPdfFinal,
        slotForzado: slotForzado,
      );
    } else {
      String texto = '';
      try {
        texto = await compute(extraerTextoPptxOptimizadoEnIsolate, bytes);
      } catch (_) {
        texto = utf8.decode(bytes, allowMalformed: true);
      }
      await _agregarOActivarPpt(
        nombre: nombre,
        textoExtraido: texto,
        autor: _aliasUsuario,
        slotForzado: slotForzado,
      );
    }
  }

  Future<void> _cargarArchivoPptOPdf(File archivo, {int? slotForzado}) async {
    final nombre = archivo.path.split('/').last;
    final ext = nombre.toLowerCase();
    try {
      if (ext.endsWith('.pptx')) {
        // Extraccion directa en Kotlin desde el archivo sin leer megabytes en Dart
        final textoFast = await _notifChannel.invokeMethod<String>(
          'extractPptxFromPath',
          {'path': archivo.path},
        );
        if (textoFast != null && textoFast.isNotEmpty) {
          await _agregarOActivarPpt(
            nombre: nombre,
            textoExtraido: textoFast,
            autor: _aliasUsuario,
            slotForzado: slotForzado,
          );
          return;
        }
      }
      final bytes = await archivo.readAsBytes();
      await _procesarBytesDeArchivoSubido(
        nombre,
        bytes,
        rutaArchivoOriginal: archivo.path,
        slotForzado: slotForzado,
      );
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error al leer el archivo: $e')),
        );
      }
    }
  }

  Future<List<File>> _buscarArchivosPptEnTelefono() async {
    final rutasBusqueda = [
      '/storage/emulated/0/Download',
      '/storage/emulated/0/Documents',
      '/storage/emulated/0/Pictures/SayCheese',
      '/storage/emulated/0/DCIM/SayCheese',
      '/storage/emulated/0/Android/media/com.whatsapp/WhatsApp/Media/WhatsApp Documents',
    ];
    final List<File> encontrados = [];

    for (final ruta in rutasBusqueda) {
      try {
        final dir = Directory(ruta);
        if (await dir.exists()) {
          final entidades = dir.listSync(recursive: false);
          for (final ent in entidades) {
            if (ent is File) {
              final name = ent.path.split('/').last;
              if (name.startsWith('.')) continue;
              final p = ent.path.toLowerCase();
              if (p.endsWith('.pptx') ||
                  p.endsWith('.pdf') ||
                  p.endsWith('.txt')) {
                encontrados.add(ent);
              }
            }
          }
        }
      } catch (_) {}
    }
    encontrados
        .sort((a, b) => b.lastModifiedSync().compareTo(a.lastModifiedSync()));
    return encontrados;
  }

  Future<void> _mostrarExploradorInternoDeArchivos(
      {required bool paraFoto, int? slotForzado}) async {
    await [
      Permission.photos,
      Permission.storage,
      Permission.manageExternalStorage,
    ].request();

    if (paraFoto) {
      await _mostrarSelectorVisualDeGaleria();
      return;
    }

    final archivos = await _buscarArchivosPptEnTelefono();
    final Set<String> seleccionados = {};

    if (!mounted) return;
    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setModalState) => AlertDialog(
          backgroundColor: const Color(0xFF1E1F20),
          title: const Text('Archivos PPTX / PDF en el Telefono'),
          content: SizedBox(
            width: double.maxFinite,
            height: 340,
            child: archivos.isEmpty
                ? const Center(
                    child: Text(
                        'No se encontraron archivos .pptx o .pdf en Descargas.'))
                : ListView.builder(
                    itemCount: archivos.length,
                    itemBuilder: (_, i) {
                      final f = archivos[i];
                      final name = f.path.split('/').last;
                      final marcado = seleccionados.contains(f.path);
                      return Card(
                        color: marcado
                            ? const Color(0xFF004A77)
                            : const Color(0xFF282A2C),
                        margin: const EdgeInsets.only(bottom: 6),
                        child: ListTile(
                          leading: Icon(
                              marcado
                                  ? Icons.check_box
                                  : Icons.check_box_outline_blank,
                              color: marcado
                                  ? const Color(0xFFA8C7FA)
                                  : Colors.white54),
                          title: Text(name,
                              maxLines: 1, overflow: TextOverflow.ellipsis),
                          subtitle: Text(f.parent.path,
                              style: const TextStyle(fontSize: 10)),
                          onTap: () {
                            setModalState(() {
                              if (marcado) {
                                seleccionados.remove(f.path);
                              } else {
                                if (seleccionados.length >= 2) {
                                  seleccionados.remove(seleccionados.first);
                                }
                                seleccionados.add(f.path);
                              }
                            });
                          },
                        ),
                      );
                    },
                  ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Cerrar'),
            ),
            if (archivos.isNotEmpty)
              FilledButton.icon(
                icon: const Icon(Icons.bolt),
                label: Text('Activar (${seleccionados.length}/2)'),
                onPressed: seleccionados.isEmpty
                    ? null
                    : () async {
                        Navigator.pop(ctx);
                        if (mounted) setState(() => _cargandoPpts = true);
                        try {
                          final listaRutas = seleccionados.take(2).toList();
                          await Future.wait(
                            List.generate(listaRutas.length, (idx) {
                              return _cargarArchivoPptOPdf(
                                File(listaRutas[idx]),
                                slotForzado: slotForzado ??
                                    (listaRutas.length == 2 ? idx : null),
                              );
                            }),
                          );
                        } finally {
                          if (mounted) setState(() => _cargandoPpts = false);
                        }
                      },
              ),
          ],
        ),
      ),
    );
  }

