  String _topicoNtfyDeSala(String sala) {
    final limpio = _limpiarCodigoSala(sala).replaceAll('-', '');
    return 'sc_room_v12_$limpio';
  }

  Future<void> _publicarEventoEnSala(Map<String, dynamic> payload) async {
    if (_codigoSala.trim().isEmpty) return;
    try {
      await _esperarRedDisponible(maxIntentos: 6);
      final topic = _topicoNtfyDeSala(_codigoSala);
      final url = Uri.parse('https://ntfy.sh/$topic');

      final rawJson = jsonEncode(payload);
      final comprimido = gzip.encode(utf8.encode(rawJson));
      final b64 = base64Encode(comprimido);

      if (b64.length <= 3000) {
        final paqueteUnico = jsonEncode({'z': b64});
        await _httpClient
            .post(url, body: paqueteUnico)
            .timeout(const Duration(seconds: 10));
      } else {
        final msgId = DateTime.now().millisecondsSinceEpoch.toString();
        const tamanoChunk = 2500;
        final totalChunks = (b64.length / tamanoChunk).ceil();
        for (int i = 0; i < totalChunks; i++) {
          final inicio = i * tamanoChunk;
          final fin = min(inicio + tamanoChunk, b64.length);
          final parte = b64.substring(inicio, fin);
          final paqueteParte = jsonEncode({
            'm': msgId,
            'i': i,
            'n': totalChunks,
            'c': parte,
          });
          await _httpClient
              .post(url, body: paqueteParte)
              .timeout(const Duration(seconds: 10));
        }
      }
    } catch (_) {}
  }

  Future<void> _publicarSolucionIndividualEnSala(EjercicioResuelto e) async {
    if (_codigoSala.trim().isEmpty || e.procesando || e.solucion == null) {
      return;
    }
    String? b64Hoja;
    if (e.rutaImagen != null && File(e.rutaImagen!).existsSync()) {
      try {
        final resB64 = await _notifChannel.invokeMethod<String>('compressImage', {
          'path': e.rutaImagen!,
          'maxDim': 740,
          'quality': 52,
          'maxBytes': 48000,
        });
        if (resB64 != null && resB64.isNotEmpty) {
          b64Hoja = resB64;
        }
      } catch (_) {
        try {
          final bytes = File(e.rutaImagen!).readAsBytesSync();
          if (bytes.length < 500 * 1024) {
            b64Hoja = base64Encode(bytes);
          }
        } catch (_) {}
      }
    }

    await _publicarEventoEnSala({
      'tipo': 'solucion',
      'emisor': _aliasUsuario,
      'item': {
        'id': e.id,
        'rutaImagen': null,
        'imagenBase64': b64Hoja,
        'fecha': e.fecha.toIso8601String(),
        'autor': e.autor,
        'modeloUsado': e.modeloUsado,
        'nivelPensamientoUsado': e.nivelPensamientoUsado,
        'tokensRazonados': e.tokensRazonados,
        'nombrePptUsado': e.nombrePptUsado,
        'instruccionAdicional': e.instruccionAdicional,
        'solucion': e.solucion,
        'mensajesChat': e.mensajesChat,
        'procesando': false,
      },
    });
  }

  Future<void> _publicarPptEnSala(PptCompartido ppt) async {
    if (_codigoSala.trim().isEmpty) return;
    await _publicarEventoEnSala({
      'tipo': 'ppt',
      'emisor': _aliasUsuario,
      'ppt': {
        'id': ppt.id,
        'nombre': ppt.nombre,
        'autor': ppt.autor,
        'textoExtraido': ppt.textoExtraido,
        'fecha': ppt.fecha.toIso8601String(),
      },
    });
  }

  Future<void> _publicarEstadoCompletoEnSala() async {
    if (_codigoSala.trim().isEmpty) return;
    for (final ppt in _pptsActivos) {
      if (ppt.textoExtraido.isNotEmpty) {
        await _publicarPptEnSala(ppt);
      }
    }
    final misResueltos = _historial
        .where((e) => !e.procesando && e.solucion != null)
        .take(8)
        .toList();
    for (final item in misResueltos) {
      await _publicarSolucionIndividualEnSala(item);
    }
  }

  Future<void> _sincronizarSalaCompartida({bool silencioso = false}) async {
    if (_codigoSala.trim().isEmpty) return;
    if (!silencioso && mounted) setState(() => _sincronizando = true);

    try {
      final redOk = await _esperarRedDisponible(maxIntentos: 4);
      if (!redOk) return;
      if (!silencioso) {
        await _publicarEstadoCompletoEnSala();
      }

      final topic = _topicoNtfyDeSala(_codigoSala);
      final sinceParam =
          (_ultimoTimestampSync > 0 && silencioso) ? '$_ultimoTimestampSync' : '12h';
      final url =
          Uri.parse('https://ntfy.sh/$topic/json?poll=1&since=$sinceParam');
      final res =
          await _httpClient.get(url).timeout(const Duration(seconds: 10));

      if (res.statusCode == 200) {
        if (mounted) setState(() => _estadoSala = 'En linea');
        if (res.body.isNotEmpty) {
          final lineas = res.body.split('\n');
          final Map<String, Map<int, String>> fragmentos = {};
          final Map<String, int> totalPorMensaje = {};
          final List<Map<String, dynamic>> payloadsDecodificados = [];

          for (final linea in lineas) {
            if (linea.trim().isEmpty) continue;
            try {
              final envoltorio = jsonDecode(linea) as Map<String, dynamic>;
              if (envoltorio['time'] is int) {
                final t = envoltorio['time'] as int;
                if (t > _ultimoTimestampSync) {
                  _ultimoTimestampSync = t;
                }
              }
              if (envoltorio['event'] != 'message') continue;
              final rawMsg = envoltorio['message'] as String? ?? '';
              if (rawMsg.isEmpty) continue;

              final obj = jsonDecode(rawMsg) as Map<String, dynamic>;
              if (obj.containsKey('z')) {
                final b64 = obj['z'] as String;
                final descomprimido =
                    utf8.decode(gzip.decode(base64Decode(b64)));
                payloadsDecodificados
                    .add(jsonDecode(descomprimido) as Map<String, dynamic>);
              } else if (obj.containsKey('m') &&
                  obj.containsKey('i') &&
                  obj.containsKey('n') &&
                  obj.containsKey('c')) {
                final mId = obj['m'].toString();
                final idx = obj['i'] as int;
                final tot = obj['n'] as int;
                final chunk = obj['c'] as String;
                fragmentos.putIfAbsent(mId, () => {})[idx] = chunk;
                totalPorMensaje[mId] = tot;
              } else if (obj.containsKey('tipo')) {
                payloadsDecodificados.add(obj);
              }
            } catch (_) {}
          }

          for (final entry in fragmentos.entries) {
            final mId = entry.key;
            final partes = entry.value;
            final esperado = totalPorMensaje[mId] ?? 0;
            if (esperado > 0 && partes.length == esperado) {
              try {
                final bufferB64 = StringBuffer();
                for (int i = 0; i < esperado; i++) {
                  bufferB64.write(partes[i]);
                }
                final descomprimido = utf8
                    .decode(gzip.decode(base64Decode(bufferB64.toString())));
                payloadsDecodificados
                    .add(jsonDecode(descomprimido) as Map<String, dynamic>);
              } catch (_) {}
            }
          }

          bool huboCambiosHistorial = false;
          bool huboCambiosPpts = false;

          for (final data in payloadsDecodificados) {
            final tipo = data['tipo'] as String? ?? '';

            if (tipo == 'solucion' && data['item'] != null) {
              final itemRemoto = EjercicioResuelto.fromJson(
                  data['item'] as Map<String, dynamic>);
              if (_idsEliminados.contains(itemRemoto.id)) continue;

              final idx =
                  _historial.indexWhere((loc) => loc.id == itemRemoto.id);
              if (idx == -1) {
                itemRemoto.estadoCola = 'Listo';
                itemRemoto.progreso = 100;
                _historial.add(itemRemoto);
                huboCambiosHistorial = true;
              } else if ((_historial[idx].solucion != itemRemoto.solucion &&
                      itemRemoto.solucion != null) ||
                  _historial[idx].mensajesChat.length !=
                      itemRemoto.mensajesChat.length) {
                if (itemRemoto.solucion != null) {
                  _historial[idx].solucion = itemRemoto.solucion;
                }
                _historial[idx].modeloUsado = itemRemoto.modeloUsado;
                _historial[idx].nivelPensamientoUsado =
                    itemRemoto.nivelPensamientoUsado;
                if (itemRemoto.tokensRazonados > 0) {
                  _historial[idx].tokensRazonados = itemRemoto.tokensRazonados;
                }
                if (itemRemoto.mensajesChat.length >
                    _historial[idx].mensajesChat.length) {
                  _historial[idx].mensajesChat = itemRemoto.mensajesChat;
                }
                _historial[idx].nombrePptUsado = itemRemoto.nombrePptUsado;
                _historial[idx].instruccionAdicional =
                    itemRemoto.instruccionAdicional;
                _historial[idx].autor = itemRemoto.autor;
                _historial[idx].procesando = false;
                _historial[idx].estadoCola = 'Listo';
                _historial[idx].progreso = 100;
                huboCambiosHistorial = true;
              }
            } else if (tipo == 'ppt' && data['ppt'] != null) {
              final pptRemoto =
                  PptCompartido.fromJson(data['ppt'] as Map<String, dynamic>);
              final existePpt = _pptsDeLaSala
                  .indexWhere((p) => p.nombre == pptRemoto.nombre);
              if (existePpt == -1) {
                _pptsDeLaSala.insert(0, pptRemoto);
                huboCambiosPpts = true;
              } else if (_pptsDeLaSala[existePpt].textoExtraido !=
                  pptRemoto.textoExtraido) {
                _pptsDeLaSala[existePpt] = pptRemoto;
                huboCambiosPpts = true;
              }

              final yaActivo =
                  _pptsActivos.any((p) => p.nombre == pptRemoto.nombre);
              if (!yaActivo &&
                  _pptsActivos.length < 2 &&
                  pptRemoto.textoExtraido.isNotEmpty) {
                _pptsActivos.add(pptRemoto);
                _actualizarCacheContextoPpts();
                huboCambiosPpts = true;
              }
            } else if (tipo == 'eliminar_solucion' && data['id'] != null) {
              final idBorrar = data['id'].toString();
              if (!_idsEliminados.contains(idBorrar)) {
                _idsEliminados.add(idBorrar);
                _colaPendientes.removeWhere((e) => e.id == idBorrar);
                _historial.removeWhere((e) => e.id == idBorrar);
                huboCambiosHistorial = true;
              }
            }
          }

          if (huboCambiosHistorial || huboCambiosPpts) {
            _historial.sort((a, b) => b.fecha.compareTo(a.fecha));
            if (mounted) setState(() {});
            if (huboCambiosHistorial) await _guardarHistorialLocal();
            if (huboCambiosPpts) await _guardarPptsLocal();
          }
        }
      }
    } catch (_) {
      if (mounted) setState(() => _estadoSala = 'Reintentando...');
    } finally {
      if (!silencioso && mounted) setState(() => _sincronizando = false);
    }
  }

