  Future<void> _reintentarEnCola(
    EjercicioResuelto item, {
    String? instruccionAdicional,
  }) async {
    if (item.rutaImagen == null) return;
    final prefs = await SharedPreferences.getInstance();
    final savedMod = prefs.getString('gemini_model_v20') ??
        prefs.getString('gemini_model') ??
        _modeloSeleccionado;
    final modeloElegido = _normalizarNombreModelo(savedMod);
    final aliasElegido = prefs.getString('alias_usuario') ?? _aliasUsuario;

    final thinkingElegido =
        prefs.getString('gemini_thinking_level') ?? _nivelPensamiento;
    if (mounted) {
      setState(() {
        _modeloSeleccionado = modeloElegido;
        _nivelPensamiento = thinkingElegido;
        _aliasUsuario = aliasElegido;
        item.modeloUsado = modeloElegido;
        item.nivelPensamientoUsado = thinkingElegido;
        item.tokensRazonados = 0;
        item.autor = aliasElegido;
        item.nombrePptUsado =
            _etiquetaPptsActivos.isNotEmpty ? _etiquetaPptsActivos : null;
        item.instruccionAdicional = instruccionAdicional;
        item.procesando = true;
        item.solucion = null;
        item.estadoCola = 'Resolviendo ahora...';
        item.progreso = 12;
        _colaPendientes.removeWhere((e) => e.id == item.id);
        _colaPendientes.insert(0, item);
      });
    }
    unawaited(_ejecutarColaSecuencial());
    await _guardarHistorialLocal();
  }

  Future<void> _ejecutarColaSecuencial() async {
    if (_procesandoCola) return;
    _procesandoCola = true;

    try {
      while (_colaPendientes.isNotEmpty) {
        final actual = _colaPendientes.first;
        if (_idsEliminados.contains(actual.id) || actual.rutaImagen == null) {
          _colaPendientes.removeAt(0);
          continue;
        }

        // Actualizar el estado de todas las demas hojas en cola para que se vea claramente su turno (1 a 1)
        for (int i = 1; i < _colaPendientes.length; i++) {
          _colaPendientes[i].estadoCola =
              'Esperando turno #${i + 1} (1 a 1 sin saturar)';
          _colaPendientes[i].progreso = 4;
        }

        final totalEnColaAhora = _colaPendientes.length;
        _ultimoPorcentajeNotif = -1;

        // Pausa breve de 1.2s entre hojas consecutivas para fluidez inmediata sin saturar
        final msDesdeUltima =
            DateTime.now().difference(_ultimaPeticionGeminiFin).inMilliseconds;
        if (msDesdeUltima < 1200) {
          await Future.delayed(Duration(milliseconds: 1200 - msDesdeUltima));
        }

        final archivoFoto = File(actual.rutaImagen!);
        int tamanoBytes = 0;
        for (int w = 0; w < 4; w++) {
          if (await archivoFoto.exists()) {
            tamanoBytes = await archivoFoto.length();
            if (tamanoBytes > 512) break;
          }
          await Future.delayed(const Duration(milliseconds: 150));
        }

        await _reportarProgresoReal(
          ejercicio: actual,
          porcentaje: 8,
          fase:
              'Resolviendo 1 a 1 • Imagen leída (${(tamanoBytes / 1024).toStringAsFixed(0)} KB)...',
          totalEnCola: totalEnColaAhora,
          forzarNotificacion: true,
        );

        try {
          final resultado = await _llamarGeminiUltrarrapidoSinCortes(
            archivoFoto,
            actual.modeloUsado,
            instruccionAdicional: actual.instruccionAdicional,
            ejercicioActual: actual,
            totalEnCola: totalEnColaAhora,
          );

          _ultimaPeticionGeminiFin = DateTime.now();

          final quedanMas = _colaPendientes.length > 1;
          final tokensRaz =
              int.tryParse(resultado['tokensRazonados'] ?? '0') ?? 0;
          final nivFinal =
              resultado['nivelPensamientoFinal'] ?? actual.nivelPensamientoUsado;

          if (mounted) {
            setState(() {
              actual.solucion = _limpiarRespuestaMarkdown(resultado['texto']!);
              actual.modeloUsado = resultado['modeloFinal']!;
              actual.nivelPensamientoUsado = nivFinal;
              actual.tokensRazonados = tokensRaz;
              actual.procesando = false;
              actual.progreso = 100;
              actual.estadoCola = 'Listo';
            });
          } else {
            actual.solucion = _limpiarRespuestaMarkdown(resultado['texto']!);
            actual.modeloUsado = resultado['modeloFinal']!;
            actual.nivelPensamientoUsado = nivFinal;
            actual.tokensRazonados = tokensRaz;
            actual.procesando = false;
            actual.progreso = 100;
            actual.estadoCola = 'Listo';
          }

          await _actualizarNotificacionProgreso(
            porcentaje: 100,
            titulo: 'Hoja completada',
            detalle: '✓ ${actual.etiquetaModeloCompleta}',
            forzarNotificacionNativa: true,
          );

          await _guardarHistorialLocal();
          await _mostrarNotificacionCompletado(
            ejercicio: actual,
            quedanMasEnCola: quedanMas,
          );
          unawaited(_publicarSolucionIndividualEnSala(actual));
          _colaPendientes.removeWhere((e) => e.id == actual.id);
        } catch (e) {
          _ultimaPeticionGeminiFin = DateTime.now();
          final msgErr = e.toString();
          final esFalloRedCamara = msgErr.contains('Failed host lookup') ||
              msgErr.contains('SocketException') ||
              msgErr.contains('ESPERANDO_RED');

          if (esFalloRedCamara) {
            if (mounted) {
              setState(() {
                actual.procesando = false;
                actual.estadoCola = 'Esperando red';
                actual.solucion =
                    '⏳ Esperando reconexión automática de red tras salir de la cámara (se resolverá sola en unos segundos o toca 🔄)...';
              });
            }
            _colaPendientes.removeWhere((e) => e.id == actual.id);
            await _guardarHistorialLocal();
            break;
          } else {
            final quedanMas = _colaPendientes.length > 1;
            if (mounted) {
              setState(() {
                actual.solucion = 'Error al resolver: $e';
                actual.procesando = false;
                actual.estadoCola = 'Error';
              });
            }
            if (!quedanMas) {
              await _ocultarNotificacionProgreso();
            }
            await _guardarHistorialLocal();
            _colaPendientes.removeWhere((e) => e.id == actual.id);
          }
        }

        if (mounted) setState(() {});
      }
    } finally {
      _procesandoCola = false;
    }
  }

  String _limpiarRespuestaMarkdown(String raw) {
    var limpio = raw.replaceAll('```markdown', '').replaceAll('```', '');
    final lineas = limpio.split('\n');
    final procesadas = lineas.map((linea) {
      if (linea.startsWith('    ') &&
          !linea.trimLeft().startsWith('*') &&
          !linea.trimLeft().startsWith('-') &&
          !linea.trimLeft().startsWith('|') &&
          !RegExp(r'^\d+\.').hasMatch(linea.trimLeft())) {
        return linea.trimLeft();
      }
      return linea;
    }).toList();
    return procesadas.join('\n').trim();
  }

  // Espera inteligentemente a que el DNS de Android despierte tras usar la camara
  Future<bool> _esperarRedDisponible({int maxIntentos = 22}) async {
    try {
      unawaited(
          _notifChannel.invokeMethod('keepNetworkAwake', {'enable': true}));
    } catch (_) {}

    for (int i = 0; i < maxIntentos; i++) {
      try {
        final res =
            await InternetAddress.lookup('generativelanguage.googleapis.com')
                .timeout(const Duration(seconds: 2));
        if (res.isNotEmpty && res.first.rawAddress.isNotEmpty) {
          return true;
        }
      } catch (_) {}
      await Future.delayed(const Duration(milliseconds: 600));
    }
    return false;
  }

  Future<String> _obtenerImagenComprimidaBase64(String path) async {
    final enCache = _cacheImagenesBase64PorRuta[path];
    if (enCache != null && enCache.isNotEmpty) {
      return enCache;
    }
    try {
      final res = await _notifChannel.invokeMethod<String>(
        'compressImage',
        {'path': path, 'maxDim': 1650, 'quality': 85},
      );
      if (res != null && res.isNotEmpty) {
        if (_cacheImagenesBase64PorRuta.length > 25) {
          _cacheImagenesBase64PorRuta.remove(_cacheImagenesBase64PorRuta.keys.first);
        }
        _cacheImagenesBase64PorRuta[path] = res;
        return res;
      }
    } catch (_) {}
    final fallback = await compute(leerYCodificarImagenEnIsolate, path);
    _cacheImagenesBase64PorRuta[path] = fallback;
    return fallback;
  }

  Future<Map<String, String>> _llamarGeminiUltrarrapidoSinCortes(
    File imagen,
    String modeloElegido, {
    String? instruccionAdicional,
    EjercicioResuelto? ejercicioActual,
    int totalEnCola = 1,
  }) async {
    final keyLimpia = _apiKey.trim();
    if (keyLimpia.isEmpty) {
      throw Exception(
          'Configura tu API Key en el boton superior de modelo/ajustes.');
    }

    final prefs = await SharedPreferences.getInstance();
    final nivelPensamientoActual = ejercicioActual?.nivelPensamientoUsado ??
        (prefs.getString('gemini_thinking_level') ?? _nivelPensamiento);
    _nivelPensamiento = nivelPensamientoActual;

    final configModelo = _obtenerConfigModelo(modeloElegido);
    final int thinkingBudgetEstricto =
        configModelo.obtenerThinkingBudget(nivelPensamientoActual);

    final base64Image = await _obtenerImagenComprimidaBase64(imagen.path);
    final kbImagen = (base64Image.length * 3 / 4 / 1024).toStringAsFixed(0);

    if (ejercicioActual != null) {
      await _reportarProgresoReal(
        ejercicio: ejercicioActual,
        porcentaje: 16,
        fase:
            'Imagen procesada ($kbImagen KB) • Iniciando ${configModelo.id} ($nivelPensamientoActual)...',
        totalEnCola: totalEnCola,
        forzarNotificacion: true,
      );
    }

    final bool ignorarPptPorInstruccion = instruccionAdicional != null &&
        instruccionAdicional.toLowerCase().contains('ignorar ppt');

    final String promptBase =
        "Resuelve TODOS los ejercicios de esta imagen con EXACTITUD ABSOLUTA A LA PRIMERA, de forma DIRECTA, CLARA y AL GRANO.\n"
        "${configModelo.instruccionExtra}\n\n"
        "🔒 REGLAS ESTRICTAS DE PRECISIÓN (CÚMPLELAS OBLIGATORIAMENTE):\n"
        "1. LECTURA VISUAL EXACTA (OCR): Lee con máxima atención cada número, coma/punto decimal, unidad (g, mg, mol, L, mL, M, %), fórmula química (ej. CaCO₃, HCl, CO₂, H₂O), signo (+/-), subrayado y encabezado de tabla. Verifica si la pregunta pide la opción CORRECTA o la INCORRECTA / FALSA / EXCEPTO.\n"
        "2. CÁLCULOS DE QUÍMICA, FÍSICA Y MATEMÁTICAS (CERO ERRORES ARITMÉTICOS):\n"
        "   - No adivines ni saltes pasos. En cada ejercicio numérico o de estequiometría escribe en 2 o 3 líneas claras: **Datos**, **Ecuación/Desarrollo con reemplazo numérico** y **Resultado final en negrita**.\n"
        "   - En Química: verifica que la ecuación química esté balanceada, usa masas molares exactas (ej. Ca=40, C=12, O=16 → CaCO₃ = 100 g/mol), comprueba reactivo limitante, pureza o rendimiento si el enunciado los menciona, y recalcula la multiplicación/división en sentido inverso para confirmar que el número es 100% exacto.\n"
        "3. GRAMÁTICA, ORACIONES DE RELATIVO Y LENGUAJE:\n"
        "   - Identifica el antecedente exacto y la función sintáctica. Recuerda que 'cuyo/a/os/as' expresa posesión y concuerda SIEMPRE en género y número con el sustantivo poseído (nunca con el poseedor), 'quien/es' exige antecedente de persona, y verifica qué preposición rige el verbo subordinado (queísmo/dequeísmo). En bancos de palabras, asigna primero las opciones unívocas y comprueba que todas las oraciones queden gramaticalmente perfectas.\n"
        "4. FORMATO DE SALIDA:\n"
        "   - CERO SALUDOS: Empieza directamente en '### Ejercicio 1' (o el número/ítem exacto de la hoja).\n"
        "   - TABLAS: Si en la hoja impresa hay una tabla o cuadro para rellenar, dibuja la Tabla Markdown completa. Si no hay tabla en la hoja, NO uses tablas.\n"
        "   - Destaca siempre en **negrita** la letra de la alternativa correcta o el resultado final."
        "${(instruccionAdicional != null && instruccionAdicional.trim().isNotEmpty) ? '\n\n⚠️ INSTRUCCIÓN PRIORITARIA DEL USUARIO (CÚMPLELA OBLIGATORIAMENTE Y VERIFICA EL RESULTADO):\n${instruccionAdicional.trim()}' : ''}";

    String promptFinal = promptBase;
    if (!ignorarPptPorInstruccion && _cacheContextoPpts.isNotEmpty) {
      promptFinal +=
          "\n\n📚 MATERIAL DE REFERENCIA CARGADO (PPT / PDF):\n"
          "- ATENCIÓN: Primero verifica si la hoja de la imagen trata sobre el MISMO tema de este material.\n"
          "- SI ES DEL MISMO TEMA: Aplica estrictamente las reglas, criterios, fórmulas y ejemplos de este material.\n"
          "- SI LA HOJA ES DE OTRA MATERIA DISTINTA (por ejemplo, si el PPT es de Lenguaje/Gramática pero la foto es de Química/Matemáticas o viceversa): IGNORA COMPLETAMENTE este material y resuelve la hoja con exactitud experta en su materia:\n"
          "$_cacheContextoPpts";
    }

    // Enviar la IMAGEN en primer lugar (parts[0]) mejora la atencion visual del modelo sobre cada numero y palabra de la hoja
    final List<Map<String, dynamic>> parts = [
      {
        "inline_data": {
          "mime_type": "image/jpeg",
          "data": base64Image,
        }
      },
      {"text": promptFinal},
    ];

    // Solo adjuntar el binario PDF si aun no se ha extraido su texto en _cacheContextoPpts y pesa menos de 4 MB
    if (!ignorarPptPorInstruccion) {
      for (final p in _pptsActivos) {
        if (p.textoExtraido.startsWith('[PDF Activo:') &&
            p.rutaLocalPdf != null &&
            p.rutaLocalPdf!.isNotEmpty) {
          final pdfFile = File(p.rutaLocalPdf!);
          if (await pdfFile.exists()) {
            final len = await pdfFile.length();
            if (len <= 4 * 1024 * 1024) {
              final b64Pdf =
                  await compute(leerYCodificarImagenEnIsolate, pdfFile.path);
              parts.add({
                "inline_data": {
                  "mime_type": "application/pdf",
                  "data": b64Pdf,
                }
              });
            }
          }
        }
      }
    }

    final redLista = await _esperarRedDisponible(maxIntentos: 14);
    if (!redLista) {
      throw Exception('ESPERANDO_RED: Failed host lookup');
    }

    if (ejercicioActual != null) {
      await _reportarProgresoReal(
        ejercicio: ejercicioActual,
        porcentaje: 24,
        fase:
            'Conectado a Google AI • Enviando a ${configModelo.id} (Pensamiento $nivelPensamientoActual)...',
        totalEnCola: totalEnCola,
        forzarNotificacion: true,
      );
    }

    final List<String> candidatos = configModelo.endpointsEstrictos
        .where((e) => !_modelosNoEncontrados404.contains(e))
        .toList();
    if (candidatos.isEmpty) {
      candidatos.addAll(configModelo.endpointsEstrictos);
    }

    String ultimoDetalleError = '';

    for (int idxCandidato = 0; idxCandidato < candidatos.length; idxCandidato++) {
      final modCandidato = candidatos[idxCandidato];
      bool usarThinkingBudgetExplicito =
          thinkingBudgetEstricto > 0 && !modCandidato.contains('lite');

      // En el motor primario (ej. gemini-3.1-pro-preview) hace hasta 3 intentos reales para nunca bajar de modelo por un 429 momentaneo
      final int maxIntentosEnEsteEndpoint = idxCandidato == 0 ? 3 : 2;

      for (int intentoPro = 0;
          intentoPro < maxIntentosEnEsteEndpoint;
          intentoPro++) {
        final Map<String, dynamic> genConfig = {
          "maxOutputTokens": 8192,
          "temperature": configModelo.temperature,
        };

        if (usarThinkingBudgetExplicito) {
          genConfig["thinkingConfig"] = {
            "thinkingBudget": thinkingBudgetEstricto,
          };
        }

        final Map<String, dynamic> payload = {
          "systemInstruction": {
            "parts": [
              {
                "text":
                    "Eres ${configModelo.id} operando en Nivel de Pensamiento $nivelPensamientoActual. "
                    "Tu prioridad absoluta es entregar soluciones 100% EXACTAS Y VERIFICADAS. "
                    "En ejercicios matemáticos o químicos, muestra los datos leídos, la ecuación o relación estequiométrica, el reemplazo numérico paso a paso y verifica la aritmética en sentido inverso antes de escribir el resultado final en negrita."
              }
            ]
          },
          "contents": [
            {"parts": parts}
          ],
          "generationConfig": genConfig,
        };

        final urlStream = Uri.parse(
          'https://generativelanguage.googleapis.com/v1beta/models/$modCandidato:streamGenerateContent?alt=sse&key=$keyLimpia',
        );

        if (ejercicioActual != null) {
          await _reportarProgresoReal(
            ejercicio: ejercicioActual,
            porcentaje: 30,
            fase:
                'Analizando en ${configModelo.id} (Pensamiento $nivelPensamientoActual)...',
            totalEnCola: totalEnCola,
            forzarNotificacion: true,
          );
        }

        Timer? monitorRazonamientoReal;
        final inicioSolicitud = DateTime.now();
        bool recibiendoTextoSolucion = false;
        int tokensPensamientoReportados = 0;

        if (ejercicioActual != null) {
          final segundosEstimadosPensamiento =
              modCandidato.contains('pro')
                  ? (nivelPensamientoActual == 'Alto'
                      ? 12
                      : (nivelPensamientoActual == 'Medio' ? 8 : 5))
                  : (nivelPensamientoActual == 'Alto' ? 6 : 4);

          monitorRazonamientoReal = Timer.periodic(
            const Duration(milliseconds: 700),
            (timer) {
              if (recibiendoTextoSolucion || !_procesandoCola) {
                timer.cancel();
                return;
              }
              final segTranscurridos =
                  DateTime.now().difference(inicioSolicitud).inMilliseconds /
                      1000.0;
              final ratio = (segTranscurridos / segundosEstimadosPensamiento)
                  .clamp(0.04, 0.98);
              final pctPensamiento = 32 + (ratio * 36).round();
              if (pctPensamiento > ejercicioActual.progreso &&
                  pctPensamiento <= 68) {
                final infoTok = tokensPensamientoReportados > 0
                    ? '${formatearNumeroConComas(tokensPensamientoReportados)} tokens razonados'
                    : '${segTranscurridos.toStringAsFixed(0)}s';
                unawaited(_reportarProgresoReal(
                  ejercicio: ejercicioActual,
                  porcentaje: pctPensamiento,
                  fase:
                      'Razonando en ${configModelo.id} • Pensamiento $nivelPensamientoActual ($infoTok)...',
                  totalEnCola: totalEnCola,
                ));
              }
            },
          );
        }

        try {
          final request = http.Request('POST', urlStream);
          request.headers['Content-Type'] = 'application/json';
          request.headers['Accept'] = 'text/event-stream';
          request.body = jsonEncode(payload);

          final streamedResponse = await _httpClient
              .send(request)
              .timeout(const Duration(seconds: 38));

          if (streamedResponse.statusCode != 200) {
            monitorRazonamientoReal?.cancel();
            final errStr = await streamedResponse.stream.bytesToString();
            if (streamedResponse.statusCode == 404) {
              _modelosNoEncontrados404.add(modCandidato);
              break;
            } else if (streamedResponse.statusCode == 400 &&
                usarThinkingBudgetExplicito) {
              usarThinkingBudgetExplicito = false;
              continue;
            } else if (streamedResponse.statusCode == 429 ||
                streamedResponse.statusCode >= 500) {
              if (esCuotaDiariaAgotada429(errStr) ||
                  intentoPro >= maxIntentosEnEsteEndpoint - 1) {
                ultimoDetalleError =
                    'Límite temporal de API en ${configModelo.id}, pasando a respaldo...';
                break;
              }

              final segEspera = extraerSegundosEspera429(errStr, intentoPro);
              for (int s = segEspera; s > 0; s--) {
                if (ejercicioActual != null) {
                  await _reportarProgresoReal(
                    ejercicio: ejercicioActual,
                    porcentaje: 31,
                    fase:
                        'Enfriando ${configModelo.id} (${s}s) para mantener máxima precisión...',
                    totalEnCola: totalEnCola,
                    forzarNotificacion: s == segEspera || s % 2 == 0,
                  );
                }
                await Future.delayed(const Duration(seconds: 1));
              }
              continue;
            } else {
              ultimoDetalleError =
                  'Error HTTP ${streamedResponse.statusCode} en ${configModelo.id}';
              break;
            }
          }

          final bufferRespuesta = StringBuffer();
          String ultimoTextoPensamiento = '';

          final lineStream = streamedResponse.stream
              .transform(utf8.decoder)
              .transform(const LineSplitter())
              .timeout(const Duration(seconds: 48));

          await for (final rawLine in lineStream) {
            final line = rawLine.trim();
            if (!line.startsWith('data:')) continue;
            final dataStr = line.substring(5).trim();
            if (dataStr.isEmpty || dataStr == '[DONE]') continue;

            Map<String, dynamic> chunk;
            try {
              chunk = jsonDecode(dataStr) as Map<String, dynamic>;
            } catch (_) {
              continue;
            }

            final usage = chunk['usageMetadata'] as Map<String, dynamic>?;
            if (usage != null) {
              final int? directThoughts =
                  (usage['thoughtsTokenCount'] as num?)?.toInt();
              if (directThoughts != null && directThoughts > 0) {
                tokensPensamientoReportados = directThoughts;
              } else {
                final int totalTok =
                    (usage['totalTokenCount'] as num?)?.toInt() ?? 0;
                final int promptTok =
                    (usage['promptTokenCount'] as num?)?.toInt() ?? 0;
                final int candTok =
                    (usage['candidatesTokenCount'] as num?)?.toInt() ?? 0;
                final int diffTok = totalTok - promptTok - candTok;
                if (diffTok > tokensPensamientoReportados) {
                  tokensPensamientoReportados = diffTok;
                }
              }
            }

            final candidates = chunk['candidates'] as List? ?? [];
            if (candidates.isNotEmpty) {
              final contentMap =
                  candidates[0]['content'] as Map<String, dynamic>?;
              final respParts = contentMap?['parts'] as List? ?? [];
              for (final p in respParts) {
                if (p is Map && p.containsKey('text')) {
                  final t = p['text']?.toString() ?? '';
                  if (t.isEmpty) continue;
                  if (p['thought'] == true) {
                    ultimoTextoPensamiento = t;
                  } else {
                    recibiendoTextoSolucion = true;
                    monitorRazonamientoReal?.cancel();
                    bufferRespuesta.write(t);
                  }
                }
              }
            }

            if (ejercicioActual != null && bufferRespuesta.isNotEmpty) {
              final textoParcial = bufferRespuesta.toString();
              final charsEscritos = textoParcial.length;
              final numEjercicios =
                  RegExp(r'###\s+').allMatches(textoParcial).length;

              ejercicioActual.solucion =
                  _limpiarRespuestaMarkdown(textoParcial);
              if (tokensPensamientoReportados > 0) {
                ejercicioActual.tokensRazonados = tokensPensamientoReportados;
              }

              final ratioEscritura =
                  (charsEscritos / 1300.0).clamp(0.04, 1.0);
              final pctRealEscritura =
                  70 + (ratioEscritura * 27).round();

              final detalleEj = numEjercicios > 0
                  ? 'Ejercicio #$numEjercicios • '
                  : '';
              final detalleTok = tokensPensamientoReportados > 0
                  ? ' • ${formatearNumeroConComas(tokensPensamientoReportados)} tokens razonados'
                  : '';
              await _reportarProgresoReal(
                ejercicio: ejercicioActual,
                porcentaje: pctRealEscritura.clamp(70, 97),
                fase:
                    'Recibiendo de ${configModelo.id} (${detalleEj}$charsEscritos chars$detalleTok)...',
                totalEnCola: totalEnCola,
              );
            }
          }

          monitorRazonamientoReal?.cancel();

          final textoFinal = bufferRespuesta.toString().trim().isNotEmpty
              ? bufferRespuesta.toString().trim()
              : ultimoTextoPensamiento.trim();

          if (textoFinal.isNotEmpty) {
            return {
              'texto': textoFinal,
              'modeloFinal': configModelo.id,
              'nivelPensamientoFinal': nivelPensamientoActual,
              'tokensRazonados': tokensPensamientoReportados.toString(),
            };
          } else if (usarThinkingBudgetExplicito) {
            usarThinkingBudgetExplicito = false;
            continue;
          }
        } on TimeoutException {
          monitorRazonamientoReal?.cancel();
          ultimoDetalleError =
              'Tiempo extendido en ${configModelo.id}, reintentando...';
          continue;
        } on SocketException catch (se) {
          monitorRazonamientoReal?.cancel();
          ultimoDetalleError = 'ESPERANDO_RED: ${se.message}';
          final recupero = await _esperarRedDisponible(maxIntentos: 6);
          if (!recupero) {
            throw Exception('ESPERANDO_RED: Failed host lookup');
          }
          continue;
        } on http.ClientException {
          monitorRazonamientoReal?.cancel();
          ultimoDetalleError = 'Reconectando con ${configModelo.id}...';
          continue;
        } catch (e) {
          monitorRazonamientoReal?.cancel();
          ultimoDetalleError = e.toString();
          break;
        } finally {
          monitorRazonamientoReal?.cancel();
        }
      }
    }

    throw Exception(ultimoDetalleError.isNotEmpty
        ? ultimoDetalleError
        : 'Servidor ocupado en ${configModelo.id}. Toca 🔄 para reintentar al instante.');
  }

