  final EjercicioResuelto ejercicio;
  final String apiKey;
  final String cacheContextoPpts;
  final Future<String> Function(String path) obtenerImagenBase64;
  final Future<void> Function() onGuardarYSincronizar;
  final VoidCallback? onReintentar;
  final VoidCallback? onEliminar;

  const DetalleSolucionScreen({
    super.key,
    required this.ejercicio,
    required this.apiKey,
    required this.cacheContextoPpts,
    required this.obtenerImagenBase64,
    required this.onGuardarYSincronizar,
    this.onReintentar,
    this.onEliminar,
  });

  @override
  State<DetalleSolucionScreen> createState() => _DetalleSolucionScreenState();
}

class _DetalleSolucionScreenState extends State<DetalleSolucionScreen> {
  bool _mostrarMiniaturaFoto = false;
  final TextEditingController _chatCtrl = TextEditingController();
  final ScrollController _scrollCtrl = ScrollController();
  final http.Client _chatHttpClient = http.Client();
  bool _enviandoPreguntaChat = false;
  String _estadoMiniChat = '';
  String _respuestaParcialMiniChat = '';

  static const List<String> _sugerenciasMiniChat = [
    '¿Por qué esa es la correcta?',
    'Justificación más corta',
    'Verifica el cálculo paso a paso',
    'Resuelve de nuevo solo la última',
  ];

  @override
  void dispose() {
    _chatCtrl.dispose();
    _scrollCtrl.dispose();
    _chatHttpClient.close();
    super.dispose();
  }

  void _hacerScrollAlFinal() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scrollCtrl.hasClients) {
        _scrollCtrl.animateTo(
          _scrollCtrl.position.maxScrollExtent,
          duration: const Duration(milliseconds: 280),
          curve: Curves.easeOut,
        );
      }
    });
  }

  // Ejecuta la pregunta puntual del Mini-Chat usando ESTRICTAMENTE el mismo modelo y el mismo Nivel de Pensamiento con que se resolvio la hoja
  Future<void> _enviarPreguntaMiniChat([String? textoDirecto]) async {
    final pregunta = (textoDirecto ?? _chatCtrl.text).trim();
    if (pregunta.isEmpty || _enviandoPreguntaChat) return;

    final keyLimpia = widget.apiKey.trim();
    if (keyLimpia.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Configura primero tu API Key en ajustes.')),
      );
      return;
    }

    final modeloHoja =
        normalizarAModeloDeLosCuatro(widget.ejercicio.modeloUsado);
    final nivelHoja = widget.ejercicio.nivelPensamientoUsado.isNotEmpty
        ? widget.ejercicio.nivelPensamientoUsado
        : 'Alto';
    final configModelo = obtenerConfigGlobalModelo(modeloHoja);
    final int budgetEstricto = configModelo.obtenerThinkingBudget(nivelHoja);

    if (textoDirecto == null) {
      _chatCtrl.clear();
    }

    setState(() {
      widget.ejercicio.mensajesChat.add({
        'rol': 'user',
        'texto': pregunta,
        'fecha': DateTime.now().toIso8601String(),
      });
      _enviandoPreguntaChat = true;
      _respuestaParcialMiniChat = '';
      _estadoMiniChat =
          'Razonando con $modeloHoja • Pensamiento $nivelHoja...';
    });
    _hacerScrollAlFinal();

    try {
      final List<Map<String, dynamic>> parts = [];

      // Si la foto original de la hoja esta en el dispositivo, la incluimos para que Gemini vea exactamente el mismo documento
      if (widget.ejercicio.rutaImagen != null &&
          File(widget.ejercicio.rutaImagen!).existsSync()) {
        try {
          final b64Img =
              await widget.obtenerImagenBase64(widget.ejercicio.rutaImagen!);
          parts.add({
            "inline_data": {
              "mime_type": "image/jpeg",
              "data": b64Img,
            }
          });
        } catch (_) {}
      }

      final sbContexto = StringBuffer();
      if (widget.cacheContextoPpts.isNotEmpty) {
        sbContexto.writeln(
            '=== MATERIAL PPT DE REFERENCIA (ÚSALO SI CORRESPONDE AL TEMA) ===');
        sbContexto.writeln(widget.cacheContextoPpts);
        sbContexto.writeln('=== FIN PPT ===\n');
      }

      sbContexto.writeln('=== SOLUCIÓN INICIAL DE ESTA HOJA ===');
      sbContexto.writeln(widget.ejercicio.solucion ?? '');
      sbContexto.writeln('=== FIN SOLUCIÓN INICIAL ===\n');

      // Incluir historial previo del Mini-Chat de esta hoja (excepto la pregunta actual que va al final)
      if (widget.ejercicio.mensajesChat.length > 1) {
        sbContexto.writeln('=== CONSULTAS PREVIAS SOBRE ESTA HOJA ===');
        for (int i = 0; i < widget.ejercicio.mensajesChat.length - 1; i++) {
          final m = widget.ejercicio.mensajesChat[i];
          final rol = m['rol'] == 'user' ? 'Alumno' : modeloHoja;
          sbContexto.writeln('$rol: ${m['texto']}');
        }
        sbContexto.writeln('=== FIN CONSULTAS PREVIAS ===\n');
      }

      sbContexto.writeln(
          'CONSULTA PUNTUAL DEL ALUMNO SOBRE ESTA HOJA: "$pregunta"\n'
          'Responde de forma DIRECTA, EXACTA y CONCISA manteniendo el rigor de $modeloHoja en Pensamiento $nivelHoja.');

      parts.insert(0, {"text": sbContexto.toString()});

      final candidatos = List<String>.from(configModelo.endpointsEstrictos);
      String textoRespuestaFinal = '';
      int tokensRazonadosChat = 0;
      String ultimoError = '';

      for (final modCandidato in candidatos) {
        bool usarBudgetExplicito =
            budgetEstricto > 0 && !modCandidato.contains('lite');

        for (int intento = 0; intento < 4; intento++) {
          final Map<String, dynamic> genConfig = {
            "maxOutputTokens": 8192,
            "temperature": configModelo.temperature,
          };
          if (usarBudgetExplicito) {
            genConfig["thinkingConfig"] = {
              "thinkingBudget": budgetEstricto,
            };
          }

          final payload = {
            "systemInstruction": {
              "parts": [
                {
                  "text":
                      "Eres $modeloHoja operando estrictamente en Nivel de Pensamiento $nivelHoja. "
                      "Responde la duda puntual del usuario sobre la hoja resuelta con exactitud total a la primera, directo al grano y sin rodeos."
                }
              ]
            },
            "contents": [
              {"parts": parts}
            ],
            "generationConfig": genConfig,
          };

          final urlStream = Uri.parse(
            'https://generativelanguage.googleapis.com/v1beta/models/$modCandidato:streamGenerateContent?alt=sse&key=$keyLimpia',
          );

          try {
            final req = http.Request('POST', urlStream);
            req.headers['Content-Type'] = 'application/json';
            req.headers['Accept'] = 'text/event-stream';
            req.body = jsonEncode(payload);

            final streamedRes = await _chatHttpClient
                .send(req)
                .timeout(const Duration(seconds: 45));

            if (streamedRes.statusCode != 200) {
              final errBody = await streamedRes.stream.bytesToString();
              if (streamedRes.statusCode == 400 && usarBudgetExplicito) {
                usarBudgetExplicito = false;
                continue;
              } else if (streamedRes.statusCode == 429 ||
                  streamedRes.statusCode >= 500) {
                if (esCuotaDiariaAgotada429(errBody) || intento >= 2) {
                  ultimoError = 'Cambiando a canal anti-saturación de $modeloHoja...';
                  break;
                }
                final segEsp = extraerSegundosEspera429(errBody, intento);
                if (mounted) {
                  setState(() {
                    _estadoMiniChat =
                        'Pausa anti-saturación de $modeloHoja (${segEsp}s) en Pensamiento $nivelHoja...';
                  });
                }
                await Future.delayed(Duration(seconds: segEsp));
                continue;
              } else {
                ultimoError =
                    'Error en $modeloHoja (${streamedRes.statusCode}): $errBody';
                break;
              }
            }

            final buffer = StringBuffer();
            String ultimoPensamiento = '';

            final lineStream = streamedRes.stream
                .transform(utf8.decoder)
                .transform(const LineSplitter())
                .timeout(const Duration(seconds: 50));

            await for (final rawLine in lineStream) {
              final line = rawLine.trim();
              if (!line.startsWith('data:')) continue;
              final dataStr = line.substring(5).trim();
              if (dataStr.isEmpty || dataStr == '[DONE]') continue;

              Map<String, dynamic> chunk;
              try {
                chunk = jsonDecode(dataStr) as Map<String, dynamic>;
              } catch (_) {
                continue;
              }

              final usage = chunk['usageMetadata'] as Map<String, dynamic>?;
              if (usage != null) {
                final int? directThoughts =
                    (usage['thoughtsTokenCount'] as num?)?.toInt();
                if (directThoughts != null && directThoughts > 0) {
                  tokensRazonadosChat = directThoughts;
                } else {
                  final int totalTok =
                      (usage['totalTokenCount'] as num?)?.toInt() ?? 0;
                  final int promptTok =
                      (usage['promptTokenCount'] as num?)?.toInt() ?? 0;
                  final int candTok =
                      (usage['candidatesTokenCount'] as num?)?.toInt() ?? 0;
                  final int diffTok = totalTok - promptTok - candTok;
                  if (diffTok > tokensRazonadosChat) {
                    tokensRazonadosChat = diffTok;
                  }
                }
              }

              final candidates = chunk['candidates'] as List? ?? [];
              if (candidates.isNotEmpty) {
                final contentMap =
                    candidates[0]['content'] as Map<String, dynamic>?;
                final respParts = contentMap?['parts'] as List? ?? [];
                for (final p in respParts) {
                  if (p is Map && p.containsKey('text')) {
                    final t = p['text']?.toString() ?? '';
                    if (t.isEmpty) continue;
                    if (p['thought'] == true) {
                      ultimoPensamiento = t;
                    } else {
                      buffer.write(t);
                    }
                  }
                }
              }

              if (mounted) {
                setState(() {
                  _respuestaParcialMiniChat = buffer.toString().trim();
                  if (tokensRazonadosChat > 0) {
                    _estadoMiniChat = construirEtiquetaVerificada(
                      modelo: modeloHoja,
                      nivelPensamiento: nivelHoja,
                      tokensRazonados: tokensRazonadosChat,
                    );
                  }
                });
              }
            }

            textoRespuestaFinal = buffer.toString().trim().isNotEmpty
                ? buffer.toString().trim()
                : ultimoPensamiento.trim();

            if (textoRespuestaFinal.isNotEmpty) {
              break;
            } else if (usarBudgetExplicito) {
              usarBudgetExplicito = false;
              continue;
            }
          } on TimeoutException {
            ultimoError = 'Tiempo agotado en $modeloHoja, reintentando...';
            await Future.delayed(const Duration(seconds: 2));
            continue;
          } catch (e) {
            ultimoError = e.toString();
            await Future.delayed(const Duration(seconds: 2));
            continue;
          }
        }
        if (textoRespuestaFinal.isNotEmpty) break;
      }

      if (textoRespuestaFinal.isEmpty) {
        throw Exception(ultimoError.isNotEmpty
            ? ultimoError
            : 'No se pudo obtener respuesta de $modeloHoja.');
      }

      if (mounted) {
        setState(() {
          widget.ejercicio.mensajesChat.add({
            'rol': 'model',
            'texto': textoRespuestaFinal,
            'modelo': modeloHoja,
            'nivelPensamiento': nivelHoja,
            'tokensRazonados': tokensRazonadosChat,
            'fecha': DateTime.now().toIso8601String(),
          });
          _enviandoPreguntaChat = false;
          _respuestaParcialMiniChat = '';
          _estadoMiniChat = '';
        });
      }
      await widget.onGuardarYSincronizar();
      _hacerScrollAlFinal();
    } catch (e) {
      if (mounted) {
        setState(() {
          widget.ejercicio.mensajesChat.add({
            'rol': 'model',
            'texto': 'Error al consultar en $modeloHoja: $e',
            'modelo': modeloHoja,
            'nivelPensamiento': nivelHoja,
            'tokensRazonados': 0,
            'fecha': DateTime.now().toIso8601String(),
          });
          _enviandoPreguntaChat = false;
          _respuestaParcialMiniChat = '';
          _estadoMiniChat = '';
        });
      }
      _hacerScrollAlFinal();
    }
  }

