    private var wifiLock: WifiManager.WifiLock? = null

    @Suppress("DEPRECATION")
    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        ensureSilentChannels(nm)

        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, NOTIF_CHANNEL).setMethodCallHandler { call, result ->
            when (call.method) {
                "requestPermission" -> {
                    if (Build.VERSION.SDK_INT >= 33) {
                        if (checkSelfPermission("android.permission.POST_NOTIFICATIONS") != PackageManager.PERMISSION_GRANTED) {
                            requestPermissions(arrayOf("android.permission.POST_NOTIFICATIONS"), 9101)
                        }
                    }
                    result.success(true)
                }
                "keepNetworkAwake" -> {
                    val enable = call.argument<Boolean>("enable") ?: true
                    setLocks(enable)
                    result.success(true)
                }
                "getAllGalleryImages" -> {
                    Thread {
                        val items = mutableListOf<Map<String, String>>()
                        try {
                            val dataCol = MediaStore.Images.Media.DATA
                            val bucketCol = MediaStore.Images.Media.BUCKET_DISPLAY_NAME
                            val dateCol = MediaStore.Images.Media.DATE_MODIFIED
                            val projection = arrayOf(dataCol, bucketCol, dateCol)
                            val sortOrder = "$dateCol DESC"
                            contentResolver.query(
                                MediaStore.Images.Media.EXTERNAL_CONTENT_URI,
                                projection,
                                null,
                                null,
                                sortOrder
                            )?.use { cursor ->
                                val idxData = cursor.getColumnIndex(dataCol)
                                val idxBucket = cursor.getColumnIndex(bucketCol)
                                val idxDate = cursor.getColumnIndex(dateCol)
                                var count = 0
                                while (cursor.moveToNext() && count < 350) {
                                    if (idxData >= 0) {
                                        val p = cursor.getString(idxData)
                                        if (!p.isNullOrEmpty() && !p.contains("/.thumbnails")) {
                                            val f = File(p)
                                            if (f.exists() && f.length() > 512) {
                                                val bucket = if (idxBucket >= 0) (cursor.getString(idxBucket) ?: f.parentFile?.name ?: "Galería") else (f.parentFile?.name ?: "Galería")
                                                val mod = if (idxDate >= 0) cursor.getLong(idxDate).toString() else (f.lastModified() / 1000).toString()
                                                items.add(mapOf(
                                                    "path" to p,
                                                    "album" to bucket,
                                                    "modified" to mod
                                                ))
                                                count++
                                            }
                                        }
                                    }
                                }
                            }
                        } catch (_: Exception) {}
                        runOnUiThread { result.success(items) }
                    }.start()
                }
                "pickGalleryImage" -> {
                    if (pendingImagePickResult != null) {
                        result.error("BUSY", "Selector ya abierto", null)
                        return@setMethodCallHandler
                    }
                    pendingImagePickResult = result
                    try {
                        val intent = Intent(Intent.ACTION_GET_CONTENT).apply {
                            addCategory(Intent.CATEGORY_OPENABLE)
                            type = "image/*"
                        }
                        startActivityForResult(Intent.createChooser(intent, "Seleccionar foto de la Galería"), PICK_IMAGE_CODE)
                    } catch (e: Exception) {
                        pendingImagePickResult = null
                        result.error("PICK_IMG_ERR", e.message, null)
                    }
                }
                "scanSayCheeseMediaStore" -> {
                    Thread {
                        val paths = mutableListOf<String>()
                        try {
                            val dataCol = MediaStore.Images.Media.DATA
                            val dateCol = MediaStore.Images.Media.DATE_MODIFIED
                            val projection = arrayOf(dataCol, dateCol)
                            val selection = "LOWER($dataCol) LIKE ?"
                            val selectionArgs = arrayOf("%saycheese%")
                            val sortOrder = "$dateCol DESC"
                            contentResolver.query(
                                MediaStore.Images.Media.EXTERNAL_CONTENT_URI,
                                projection,
                                selection,
                                selectionArgs,
                                sortOrder
                            )?.use { cursor ->
                                val idx = cursor.getColumnIndex(dataCol)
                                var count = 0
                                while (cursor.moveToNext() && count < 60) {
                                    if (idx >= 0) {
                                        val p = cursor.getString(idx)
                                        if (!p.isNullOrEmpty()) {
                                            paths.add(p)
                                            count++
                                        }
                                    }
                                }
                            }
                        } catch (_: Exception) {}
                        runOnUiThread { result.success(paths) }
                    }.start()
                }
                "compressImage" -> {
                    val path = call.argument<String>("path")
                    val targetMaxDim = call.argument<Int>("maxDim") ?: 1650
                    val initialQuality = call.argument<Int>("quality") ?: 85
                    val maxBytes = call.argument<Int>("maxBytes") ?: 0
                    if (path == null) {
                        result.error("NO_PATH", "Ruta vacia", null)
                        return@setMethodCallHandler
                    }
                    Thread {
                        try {
                            val file = File(path)
                            val origBytes = file.readBytes()
                            if (maxBytes <= 0 && targetMaxDim >= 1600 && origBytes.size <= 240 * 1024) {
                                val b64 = Base64.encodeToString(origBytes, Base64.NO_WRAP)
                                runOnUiThread { result.success(b64) }
                                return@Thread
                            }
                            val opts = BitmapFactory.Options().apply { inJustDecodeBounds = true }
                            BitmapFactory.decodeByteArray(origBytes, 0, origBytes.size, opts)
                            var sampleSize = 1
                            val origMaxDim = maxOf(opts.outWidth, opts.outHeight)
                            while (origMaxDim / (sampleSize * 2) >= targetMaxDim) {
                                sampleSize *= 2
                            }
                            val decodeOpts = BitmapFactory.Options().apply { inSampleSize = sampleSize }
                            var bmp = BitmapFactory.decodeByteArray(origBytes, 0, origBytes.size, decodeOpts)
                            if (bmp != null) {
                                val curW = bmp.width
                                val curH = bmp.height
                                val curMax = maxOf(curW, curH)
                                if (curMax > targetMaxDim && targetMaxDim > 0) {
                                    val ratio = targetMaxDim.toFloat() / curMax.toFloat()
                                    val newW = maxOf(1, (curW * ratio).toInt())
                                    val newH = maxOf(1, (curH * ratio).toInt())
                                    val scaled = Bitmap.createScaledBitmap(bmp, newW, newH, true)
                                    if (scaled != bmp) {
                                        bmp.recycle()
                                        bmp = scaled
                                    }
                                }
                                val out = ByteArrayOutputStream()
                                var q = initialQuality.coerceIn(25, 95)
                                bmp.compress(Bitmap.CompressFormat.JPEG, q, out)
                                while (maxBytes > 0 && out.size() > maxBytes && q > 28) {
                                    out.reset()
                                    q -= 10
                                    bmp.compress(Bitmap.CompressFormat.JPEG, q.coerceAtLeast(25), out)
                                }
                                bmp.recycle()
                                val compressed = out.toByteArray()
                                val b64 = Base64.encodeToString(compressed, Base64.NO_WRAP)
                                runOnUiThread { result.success(b64) }
                            } else {
                                val b64 = Base64.encodeToString(origBytes, Base64.NO_WRAP)
                                runOnUiThread { result.success(b64) }
                            }
                        } catch (e: Exception) {
                            runOnUiThread { result.error("COMP_ERR", e.message, null) }
                        }
                    }.start()
                }
                "extractPptxFromPath" -> {
                    val path = call.argument<String>("path")
                    if (path == null) {
                        result.error("NO_PATH", "Ruta vacia", null)
                        return@setMethodCallHandler
                    }
                    Thread {
                        try {
                            val f = File(path)
                            val text = FileInputStream(f).use { fis ->
                                extractPptxStreamFast(fis)
                            }
                            runOnUiThread { result.success(text) }
                        } catch (e: Exception) {
                            runOnUiThread { result.error("PPT_ERR", e.message, null) }
                        }
                    }.start()
                }
                "pickPptFiles" -> {
                    if (pendingPickResult != null) {
                        result.error("BUSY", "Selector ya abierto", null)
                        return@setMethodCallHandler
                    }
                    pendingPickResult = result
                    try {
                        val intent = Intent(Intent.ACTION_OPEN_DOCUMENT).apply {
                            addCategory(Intent.CATEGORY_OPENABLE)
                            type = "*/*"
                            putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true)
                            putExtra(Intent.EXTRA_MIME_TYPES, arrayOf(
                                "application/vnd.openxmlformats-officedocument.presentationml.presentation",
                                "application/pdf",
                                "text/plain",
                                "application/octet-stream"
                            ))
                        }
                        startActivityForResult(intent, PICK_PPT_CODE)
                    } catch (e: Exception) {
                        pendingPickResult = null
                        result.error("PICK_ERR", e.message, null)
                    }
                }
                "showProgress" -> {
                    val title = call.argument<String>("title") ?: "Resolviendo hoja..."
                    val body = call.argument<String>("body") ?: "Procesando con Gemini..."
                    val progress = call.argument<Int>("progress") ?: 0
                    val maxProgress = call.argument<Int>("maxProgress") ?: 100
                    val indeterminate = call.argument<Boolean>("indeterminate") ?: false

                    setLocks(true)
                    ensureSilentChannels(nm)
                    val iconRes = if (applicationInfo.icon != 0) applicationInfo.icon else android.R.drawable.ic_popup_sync
                    val builder = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                        Notification.Builder(applicationContext, PROGRESS_CHANNEL_ID)
                    } else {
                        Notification.Builder(applicationContext)
                            .setPriority(Notification.PRIORITY_LOW)
                            .setDefaults(0)
                            .setSound(null)
                            .setVibrate(longArrayOf(0L))
                    }

                    builder.setSmallIcon(iconRes)
                        .setContentTitle(title)
                        .setContentText(body)
                        .setOngoing(true)
                        .setOnlyAlertOnce(true)
                        .setProgress(maxProgress, progress, indeterminate)

                    getLaunchPendingIntent()?.let { builder.setContentIntent(it) }
                    nm.notify(PROGRESS_NOTIF_ID, builder.build())
                    result.success(true)
                }
                "showCompleted" -> {
                    val title = call.argument<String>("title") ?: "Hoja resuelta"
                    val body = call.argument<String>("body") ?: "Toca para ver la solucion."
                    val cancelProgress = call.argument<Boolean>("cancelProgress") ?: true
                    val notifId = call.argument<Int>("id") ?: (2000 + (System.currentTimeMillis() % 1000).toInt())

                    if (cancelProgress) {
                        setLocks(false)
                        nm.cancel(PROGRESS_NOTIF_ID)
                    }

                    ensureSilentChannels(nm)
                    val iconRes = if (applicationInfo.icon != 0) applicationInfo.icon else android.R.drawable.ic_dialog_info
                    val builder = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                        Notification.Builder(applicationContext, DONE_CHANNEL_ID)
                    } else {
                        Notification.Builder(applicationContext)
                            .setPriority(Notification.PRIORITY_LOW)
                            .setDefaults(0)
                            .setSound(null)
                            .setVibrate(longArrayOf(0L))
                    }

                    builder.setSmallIcon(iconRes)
                        .setContentTitle(title)
                        .setContentText(body)
                        .setAutoCancel(true)
                        .setOnlyAlertOnce(true)
                        .setProgress(0, 0, false)

                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                        builder.setStyle(Notification.BigTextStyle().bigText(body))
                    }

                    getLaunchPendingIntent()?.let { builder.setContentIntent(it) }
                    nm.notify(notifId, builder.build())
                    result.success(true)
                }
                "cancelProgress" -> {
                    setLocks(false)
                    nm.cancel(PROGRESS_NOTIF_ID)
                    result.success(true)
                }
                else -> result.notImplemented()
            }
        }
    }

    @Suppress("DEPRECATION")
    private fun setLocks(enable: Boolean) {
        try {
            if (enable) {
                if (wakeLock == null) {
                    val pm = applicationContext.getSystemService(Context.POWER_SERVICE) as PowerManager
                    wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "SayCheese::NetWakeLock").apply {
                        setReferenceCounted(false)
                    }
                }
                if (wakeLock?.isHeld == false) {
                    wakeLock?.acquire(3 * 60 * 1000L)
                }
                if (wifiLock == null) {
                    val wm = applicationContext.getSystemService(Context.WIFI_SERVICE) as WifiManager
                    val lockType = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                        WifiManager.WIFI_MODE_FULL_LOW_LATENCY
                    } else {
                        WifiManager.WIFI_MODE_FULL_HIGH_PERF
                    }
                    wifiLock = wm.createWifiLock(lockType, "SayCheese::NetWifiLock").apply {
                        setReferenceCounted(false)
                    }
                }
                if (wifiLock?.isHeld == false) {
                    wifiLock?.acquire()
                }
            } else {
                if (wakeLock?.isHeld == true) wakeLock?.release()
                if (wifiLock?.isHeld == true) wifiLock?.release()
            }
        } catch (_: Exception) {}
    }

    // Extractor nativo completo y ultrarrapido en Kotlin:
    // Ignora los archivos multimedia pesados (imagenes/videos/fuentes) para tardar <0.1s,
    // pero extrae el 100% del texto de TODAS las diapositivas (ppt/slides/slide*.xml) y Notas del profesor (ppt/notesSlides/notesSlide*.xml) sin recortar nada.
    private fun extractPptxStreamFast(inputStream: InputStream): String {
        val slidesMap = mutableMapOf<Int, String>()
        val notesMap = mutableMapOf<Int, String>()
        val regexSlide = Regex("ppt/slides/slide(\\d+)\\.xml")
        val regexNote = Regex("ppt/notesSlides/notesSlide(\\d+)\\.xml")
        val regexP = Regex("<a:p\\b[^>]*>(.*?)</a:p>", RegexOption.DOT_MATCHES_ALL)
        val regexT = Regex("<a:t[^>]*>(.*?)</a:t>", RegexOption.DOT_MATCHES_ALL)
        val whitespaceRegex = Regex("\\s+")

        ZipInputStream(inputStream).use { zis ->
            var entry = zis.nextEntry
            while (entry != null) {
                val slideMatch = regexSlide.matchEntire(entry.name)
                val noteMatch = if (slideMatch == null) regexNote.matchEntire(entry.name) else null
                if (slideMatch != null || noteMatch != null) {
                    val num = (slideMatch ?: noteMatch)!!.groupValues[1].toIntOrNull() ?: 0
                    val xml = zis.readBytes().toString(Charsets.UTF_8)
                    val lines = mutableListOf<String>()
                    for (pMatch in regexP.findAll(xml)) {
                        val pContent = pMatch.groupValues[1]
                        val sb = StringBuilder()
                        for (tMatch in regexT.findAll(pContent)) {
                            sb.append(tMatch.groupValues[1])
                        }
                        val clean = sb.toString()
                            .replace("&amp;", "&")
                            .replace("&lt;", "<")
                            .replace("&gt;", ">")
                            .replace("&quot;", "\"")
                            .replace("&apos;", "'")
                            .replace(whitespaceRegex, " ")
                            .trim()
                        if (clean.isNotEmpty()) {
                            lines.add(clean)
                        }
                    }
                    if (lines.isNotEmpty()) {
                        if (slideMatch != null) {
                            slidesMap[num] = "[Diapositiva $num] " + lines.joinToString(" • ")
                        } else {
                            notesMap[num] = "(Notas Diapositiva $num: " + lines.joinToString(" • ") + ")"
                        }
                    }
                }
                zis.closeEntry()
                entry = zis.nextEntry
            }
        }
        val allSlideNums = (slidesMap.keys + notesMap.keys).toSortedSet()
        val finalLines = mutableListOf<String>()
        for (n in allSlideNums) {
            val sText = slidesMap[n] ?: ""
            val nText = notesMap[n] ?: ""
            val combined = listOf(sText, nText).filter { it.isNotEmpty() }.joinToString(" ")
            if (combined.isNotEmpty()) {
                finalLines.add(combined)
            }
        }
        return finalLines.joinToString("\n").trim()
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        if (requestCode == PICK_IMAGE_CODE) {
            val res = pendingImagePickResult
            pendingImagePickResult = null
            if (res == null) return
            if (resultCode != Activity.RESULT_OK || data?.data == null) {
                res.success("")
                return
            }
            val uri = data.data!!
            Thread {
                try {
                    var resolvedPath = ""
                    val dataCol = MediaStore.Images.Media.DATA
                    contentResolver.query(uri, arrayOf(dataCol), null, null, null)?.use { cursor ->
                        if (cursor.moveToFirst()) {
                            val idx = cursor.getColumnIndex(dataCol)
                            if (idx >= 0) {
                                val p = cursor.getString(idx)
                                if (!p.isNullOrEmpty() && File(p).exists()) {
                                    resolvedPath = p
                                }
                            }
                        }
                    }
                    if (resolvedPath.isEmpty()) {
                        val tempFile = File(cacheDir, "gallery_pick_${System.currentTimeMillis()}.jpg")
                        contentResolver.openInputStream(uri)?.use { input ->
                            tempFile.outputStream().use { output ->
                                input.copyTo(output)
                            }
                        }
                        if (tempFile.exists() && tempFile.length() > 512) {
                            resolvedPath = tempFile.absolutePath
                        }
                    }
                    runOnUiThread { res.success(resolvedPath) }
                } catch (e: Exception) {
                    runOnUiThread { res.error("IMG_READ_ERR", e.message, null) }
                }
            }.start()
            return
        }
        if (requestCode == PICK_PPT_CODE) {
            val res = pendingPickResult
            pendingPickResult = null
            if (res == null) return
            if (resultCode != Activity.RESULT_OK || data == null) {
                res.success(emptyList<Map<String, String>>())
                return
            }
            Thread {
                try {
                    val uris = mutableListOf<Uri>()
                    val clip = data.clipData
                    if (clip != null) {
                        val count = minOf(clip.itemCount, 2)
                        for (i in 0 until count) {
                            uris.add(clip.getItemAt(i).uri)
                        }
                    } else if (data.data != null) {
                        uris.add(data.data!!)
                    }
                    val listaArchivos = mutableListOf<Map<String, String>>()
                    for (u in uris) {
                        var nombre = "Documento_${System.currentTimeMillis()}.pptx"
                        contentResolver.query(u, null, null, null, null)?.use { cursor ->
                            if (cursor.moveToFirst()) {
                                val idx = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME)
                                if (idx >= 0) {
                                    nombre = cursor.getString(idx) ?: nombre
                                }
                            }
                        }
                        val lower = nombre.lowercase()
                        if (lower.endsWith(".pptx")) {
                            val extractedText = contentResolver.openInputStream(u)?.use { stream ->
                                extractPptxStreamFast(stream)
                            } ?: ""
                            listaArchivos.add(mapOf(
                                "name" to nombre,
                                "text" to extractedText,
                                "base64" to ""
                            ))
                        } else {
                            val bytes = contentResolver.openInputStream(u)?.use { it.readBytes() }
                            if (bytes != null && bytes.isNotEmpty()) {
                                // Intentar primero como ZIP/PPTX por si no tiene extension .pptx
                                var posibleTexto = ""
                                if (!lower.endsWith(".pdf")) {
                                    try {
                                        posibleTexto = extractPptxStreamFast(ByteArrayInputStream(bytes))
                                    } catch (_: Exception) {}
                                }
                                if (posibleTexto.isNotEmpty()) {
                                    listaArchivos.add(mapOf(
                                        "name" to nombre,
                                        "text" to posibleTexto,
                                        "base64" to ""
                                    ))
                                } else {
                                    val b64 = Base64.encodeToString(bytes, Base64.NO_WRAP)
                                    listaArchivos.add(mapOf(
                                        "name" to nombre,
                                        "text" to "",
                                        "base64" to b64
                                    ))
                                }
                            }
                        }
                    }
                    runOnUiThread { res.success(listaArchivos) }
                } catch (e: Exception) {
                    runOnUiThread { res.error("READ_ERR", e.message, null) }
                }
            }.start()
        }
    }

    private fun getLaunchPendingIntent(): PendingIntent? {
        val launchIntent = packageManager.getLaunchIntentForPackage(packageName)?.apply {
            flags = Intent.FLAG_ACTIVITY_SINGLE_TOP or Intent.FLAG_ACTIVITY_CLEAR_TOP
        } ?: return null
        val flags = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        } else {
            PendingIntent.FLAG_UPDATE_CURRENT
        }
        return PendingIntent.getActivity(applicationContext, 0, launchIntent, flags)
    }

    private fun ensureSilentChannels(nm: NotificationManager) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            try {
                nm.deleteNotificationChannel("saycheese_progress_channel")
                nm.deleteNotificationChannel("saycheese_done_channel")
                nm.deleteNotificationChannel("saycheese_done_channel_v2")
                nm.deleteNotificationChannel("saycheese_silent_progress_v19")
                nm.deleteNotificationChannel("saycheese_silent_done_v19")
                nm.deleteNotificationChannel("saycheese_silent_progress_v20")
                nm.deleteNotificationChannel("saycheese_silent_done_v20")
                nm.deleteNotificationChannel("saycheese_silent_progress_v21")
                nm.deleteNotificationChannel("saycheese_silent_done_v21")
                nm.deleteNotificationChannel("saycheese_silent_progress_v22")
                nm.deleteNotificationChannel("saycheese_silent_done_v22")
            } catch (_: Exception) {}

            val progressChannel = NotificationChannel(
                PROGRESS_CHANNEL_ID,
                "Progreso Silencioso",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Barra de progreso sin sonido ni vibracion"
                enableVibration(false)
                vibrationPattern = longArrayOf(0L)
                setSound(null, null)
                enableLights(false)
            }
            val doneChannel = NotificationChannel(
                DONE_CHANNEL_ID,
                "Resultados Silenciosos",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Aviso 100% silencioso cuando la hoja esta lista"
                enableVibration(false)
                vibrationPattern = longArrayOf(0L)
                setSound(null, null)
                enableLights(false)
            }
            nm.createNotificationChannel(progressChannel)
            nm.createNotificationChannel(doneChannel)
        }
    }
